const item = $input.first();
let text = '';
if (item.binary && item.binary.data) {
  text = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
} else {
  const raw = item.json.body ?? item.json.data ?? item.json;
  if (typeof raw === 'string') text = raw;
  else if (raw && typeof raw === 'object' && typeof raw.body === 'string') text = raw.body;
  else if (raw && typeof raw === 'object') {
    return [{
      json: {
        submitted_at: raw.submitted_at || new Date().toISOString(),
        business_name: raw.business_name || '',
        business_type: raw.business_type || '',
        contact_name: raw.contact_name || '',
        contact_email: raw.contact_email || '',
        phone: raw.phone || '',
        service_area: raw.service_area || '',
        core_services: raw.core_services || '',
        offer: raw.offer || '',
        trust_points: raw.trust_points || '',
        landing_page_url: raw.landing_page_url || '',
        campaign_goal: raw.campaign_goal || '',
        cta: raw.cta || '',
        notes: raw.notes || '',
        status: raw.status || 'submitted',
        source: raw.source || 'victorialeads.ca',
      },
    }];
  }
}
let parsed;
try { parsed = JSON.parse(text); } catch (e) {
  throw new Error('Webhook body is not valid JSON: ' + String(text).slice(0, 200));
}
return [{
  json: {
    submitted_at: parsed.submitted_at || new Date().toISOString(),
    business_name: parsed.business_name || '',
    business_type: parsed.business_type || '',
    contact_name: parsed.contact_name || '',
    contact_email: parsed.contact_email || '',
    phone: parsed.phone || '',
    service_area: parsed.service_area || '',
    core_services: parsed.core_services || '',
    offer: parsed.offer || '',
    trust_points: parsed.trust_points || '',
    landing_page_url: parsed.landing_page_url || '',
    campaign_goal: parsed.campaign_goal || '',
    cta: parsed.cta || '',
    notes: parsed.notes || '',
    status: parsed.status || 'submitted',
    source: parsed.source || 'victorialeads.ca',
  },
}];
